  /**
   * @method
   * @name bitvavo#createOrderWs
   * @description create a trade order
   * @see https://docs.bitvavo.com/#tag/Orders/paths/~1order/post
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} price the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.timeInForce] "GTC", "IOC", or "PO"
   * @param {float} [params.stopPrice] The price at which a trigger order is
   * triggered at
   * @param {float} [params.triggerPrice] The price at which a trigger order is
   * triggered at
   * @param {bool} [params.postOnly] If true, the order will only be posted to
   * the order book and not executed immediately
   * @param {float} [params.stopLossPrice] The price at which a stop loss order
   * is triggered at
   * @param {float} [params.takeProfitPrice] The price at which a take profit
   * order is triggered at
   * @param {string} [params.triggerType] "price"
   * @param {string} [params.triggerReference] "lastTrade", "bestBid",
   * "bestAsk", "midPrice" Only for stop orders: Use this to determine which
   * parameter will trigger the order
   * @param {string} [params.selfTradePrevention] "decrementAndCancel",
   * "cancelOldest", "cancelNewest", "cancelBoth"
   * @param {bool} [params.disableMarketProtection] don't cancel if the next
   * fill price is 10% worse than the best fill price
   * @param {bool} [params.responseRequired] Set this to 'false' when only an
   * acknowledgement of success or failure is required, this is faster.
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrderWs(std::any symbol, std::any type, std::any side, std::any amount,
                std::any price = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        awaitValue(this->authenticate());
                        std::any request = this->createOrderRequest(
                            symbol, type, side, amount, price, params);
                        return awaitValue(this->watchRequest(
                            std::string("privateCreateOrder"), request));
                      })
        .share();
  }

